import sys

def paint_cardiogram(n, a):
    # Calculate the coordinates of the points
    x = [0]
    y = [0]
    for i in range(n):
        x.append(x[-1] + a[i])
        y.append(y[-1] + (-1)**(i+1) * a[i])

    # Determine the bounding box of the cardiogram
    min_x = min(x)
    max_x = max(x)
    min_y = min(y)
    max_y = max(y)

    # Create the grid
    width = max_x - min_x + 1
    height = max_y - min_y + 1
    grid = [[' ' for _ in range(width)] for _ in range(height)]

    # Draw the cardiogram on the grid
    for i in range(n):
        x1, y1 = x[i] - min_x, height - 1 - (y[i] - min_y)
        x2, y2 = x[i+1] - min_x, height - 1 - (y[i+1] - min_y)
        if x1 == x2:
            if y1 < y2:
                for j in range(y1, y2 + 1):
                    grid[j][x1] = '|'
            else:
                for j in range(y2, y1 + 1):
                    grid[j][x1] = '|'
        elif y1 == y2:
            if x1 < x2:
                for j in range(x1, x2 + 1):
                    grid[y1][j] = '-'
            else:
                for j in range(x2, x1 + 1):
                    grid[y1][j] = '-'
        else:
            dx = 1 if x2 > x1 else -1
            dy = 1 if y2 > y1 else -1
            while x1 != x2 or y1 != y2:
                grid[height - 1 - (y1 - min_y)][x1 - min_x] = '\\'
                x1 += dx
                y1 += dy
            grid[height - 1 - (y2 - min_y)][x2 - min_x] = '/'

    # Print the grid
    for row in grid:
        print(''.join(row))

